session_file = os.path.join(RLM_SESSION_DIR, '../../sessions/' + os.path.basename(RLM_SESSION_DIR) + '.jsonl')

with open(session_file) as f:
    content = f.read().replace('\\n', '\n')

p = r'((?:Demo pair \d+ (?:input|output))|Test input)\s*\((\d+)x(\d+)\):\n'

matches = list(re.finditer(p, content))

def extract_grid_by_pos(idx):
    m = matches[idx]
    h, w = int(m.group(2)), int(m.group(3))
    rows_start = m.end()
    remaining = content[rows_start:].split('\n')[:h]
    return [[int(x) for x in row.split()] for row in remaining]

demo_input = extract_grid_by_pos(1)
demo_output = extract_grid_by_pos(2)
bg_demo = demo_input[0][0]

def transform_row_before_col_between(grid, bg):
    """Row: fill before last; Column: fill between first and last"""
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    # Row fills: before last marker in each qualifying row
    for r in range(h):
        marker_cols = sorted([c for c in range(w) if grid[r][c] != bg])
        if len(marker_cols) >= 2:
            last_c = max(marker_cols)
            for c in range(last_c):
                if result[r][c] == bg:
                    result[r][c] = 2

    # Column fills: between first and last marker
    for c in range(w):
        marker_rows = sorted([r for r in range(h) if grid[r][c] != bg])
        if len(marker_rows) >= 2:
            first_r = min(marker_rows)
            last_r = max(marker_rows)
            for r in range(first_r, last_r):
                if result[r][c] == bg:
                    result[r][c] = 2

    return result

